    ret |= pi_ai_mic_pre_dac_write(DAC3101_R_BQD_A_N2_LO, 0x9A);
    ret |= pi_ai_mic_pre_dac_write(DAC3101_R_BQD_A_D1_HI, 0x7B);
    ret |= pi_ai_mic_pre_dac_write(DAC3101_R_BQD_A_D1_LO, 0x14);
