static int pi_ai_mic_apply_boot_detect_leds(device_control_t *device_control_gpio_ctx)
{
    uint32_t red = 0;
    uint32_t green = 0;

    if (pi_ai_mic_boot_detect_valid) {
        red = pi_ai_mic_boot_detect_jack ? 1u : 0u;
