#if PI_AI_MIC_DETECT_LED_MONITOR_DEVICE_CONTROL_ACTIVE
static void pi_ai_mic_detect_led_monitor_task(void *arg)
{
    device_control_t *device_control_gpio_ctx = (device_control_t *) arg;
    unsigned log_count = 0;
    bool state_valid = false;
    bool stable_jack = false;
    bool stable_mic_square = false;
    int amp_ret = 0;

    vTaskDelay(pdMS_TO_TICKS(PI_AI_MIC_DETECT_LED_MONITOR_START_DELAY_MS));

    for (;;) {
        uint8_t input = 0;
        int read_ret = pi_ai_mic_i2c_forced_reg_read(
                PI_AI_MIC_PCAL6408A_I2C_ADDR,
                PI_AI_MIC_PCAL6408A_INPUT_PORT,
                &input);

        if (read_ret == 0) {
            bool jack = (((input >> PCAL_JACK_DET_PIN) & 0x01u) == PI_AI_MIC_JACK_INSERTED_LEVEL);
            bool mic_square = (((input >> PCAL_MIC_DETECT_PIN) & 0x01u) == PI_AI_MIC_MIC_DETECT_SQUARE_LEVEL);

            pi_ai_mic_boot_detect_valid = 1;
            pi_ai_mic_boot_detect_jack = jack ? 1 : 0;
            pi_ai_mic_boot_detect_mic_square = mic_square ? 1 : 0;

            (void) write_gpo_pin(device_control_gpio_ctx, GPO_LED_RED_PIN, jack ? 1u : 0u);
            (void) write_gpo_pin(device_control_gpio_ctx, GPO_LED_GREEN_PIN, mic_square ? 1u : 0u);

#if PI_AI_MIC_JACK_AMP_EDGE_MONITOR_ENABLE
            if (!state_valid || jack != stable_jack) {
                amp_ret = pi_ai_mic_set_amp_mode(
                        jack ? PI_AI_MIC_AMP_SHUTDOWN : PI_AI_MIC_AMP_CLASS_D_BOOST_ACF);
            }
#endif

            if (!state_valid || jack != stable_jack || mic_square != stable_mic_square || log_count == 0) {
                rtos_printf("PI_AI_MIC detect live input=0x%02x jack=%u mic_square=%u amp_ret=%d\n",
                            input,
                            jack ? 1u : 0u,
                            mic_square ? 1u : 0u,
                            amp_ret);
            }

            stable_jack = jack;
            stable_mic_square = mic_square;
            state_valid = true;
        } else {
            if (log_count == 0) {
                rtos_printf("PI_AI_MIC detect live PCAL read failed ret=%d; keeping previous LED/amp state\n",
                            read_ret);
            }
        }

        log_count++;
        if (log_count >= PI_AI_MIC_DETECT_LED_MONITOR_LOG_PERIOD) {
            log_count = 0;
        }

        vTaskDelay(pdMS_TO_TICKS(PI_AI_MIC_DETECT_LED_MONITOR_PERIOD_MS));
    }
}

