#if PI_AI_MIC_JACK_MONITOR_ENABLE
static void pi_ai_mic_jack_monitor_task(void *arg)
{
    (void) arg;

    bool stable_jack = true;
    bool last_sample = true;
    unsigned same_count = 0;
    bool initialized = false;

    for (;;) {
        bool valid = false;
        bool sample = pi_ai_mic_jack_inserted(&valid);

        if (!valid) {
            if (!stable_jack) {
                stable_jack = true;
                (void) pi_ai_mic_apply_output_route(true, PI_AI_MIC_SPEAKER_ENABLE_WHEN_NO_JACK);
            }
            initialized = true;
            same_count = 0;
        } else if (!initialized) {
            stable_jack = sample;
            last_sample = sample;
            initialized = true;
        } else if (sample != last_sample) {
            last_sample = sample;
            same_count = 1;
        } else if (sample != stable_jack) {
            same_count++;
            if (same_count >= PI_AI_MIC_JACK_MONITOR_DEBOUNCE_COUNT) {
                stable_jack = sample;
                same_count = 0;
                (void) pi_ai_mic_apply_output_route(stable_jack, PI_AI_MIC_SPEAKER_ENABLE_WHEN_NO_JACK);
            }
        } else {
            same_count = 0;
        }

#if PI_AI_MIC_HARD_SPEAKER_MUTE
        (void) pi_ai_mic_set_amp_mode(PI_AI_MIC_AMP_SHUTDOWN);
#endif

        vTaskDelay(pdMS_TO_TICKS(PI_AI_MIC_JACK_MONITOR_PERIOD_MS));
    }
}
#endif

#if PI_AI_MIC_JACK_AMP_CUT_MONITOR_ACTIVE
static void pi_ai_mic_jack_amp_cut_monitor_task(void *arg)
{
    (void) arg;

    bool last_valid = false;
    bool last_jack = false;
    bool initialized = false;

    vTaskDelay(pdMS_TO_TICKS(PI_AI_MIC_JACK_MONITOR_START_DELAY_MS));

    for (;;) {
        bool valid = false;
        bool jack = false;
        bool mic = false;
        int ret = pi_ai_mic_read_detect_state(&valid, &jack, &mic);

        if (ret == 0 && valid) {
            pi_ai_mic_boot_detect_valid = 1;
            pi_ai_mic_boot_detect_jack = jack ? 1 : 0;
            pi_ai_mic_boot_detect_mic_square = mic ? 1 : 0;

            if (!initialized || !last_valid || jack != last_jack) {
                pi_ai_mic_amp_mode_t mode = jack ? PI_AI_MIC_AMP_SHUTDOWN : PI_AI_MIC_AMP_CLASS_D_BOOST_ACF;
                int amp_ret = pi_ai_mic_set_amp_mode(mode);
                rtos_printf("PI_AI_MIC jack amp-cut monitor P5=%u P6=%u -> AMP_CTRL1/2 %s expected_output=%s ret=%d\n",
                            jack ? 1u : 0u,
                            mic ? 1u : 0u,
                            jack ? "off" : "acf",
                            jack ? "0x05" : "0x85",
                            amp_ret);
            }

            last_valid = true;
            last_jack = jack;
            initialized = true;
        } else {
            pi_ai_mic_boot_detect_valid = 0;
            if (!initialized || last_valid) {
                rtos_printf("PI_AI_MIC jack amp-cut monitor detect read failed ret=%d\n", ret);
            }
            last_valid = false;
            initialized = true;
        }

        vTaskDelay(pdMS_TO_TICKS(PI_AI_MIC_JACK_MONITOR_PERIOD_MS));
    }
}

