static volatile uint32_t pi_ai_mic_raw_gpo_value = 0xFFu;
#if PI_AI_MIC_DETECT_LED_DIAG_PULSE_ENABLE
static volatile uint32_t pi_ai_mic_diag_pulse_value = 0xFFu;
static volatile uint32_t pi_ai_mic_diag_pulse_ticks = 0;
#endif
#if PI_AI_MIC_DETECT_LED_MONITOR_GPO_SERVICER_POLL_ACTIVE
static bool pi_ai_mic_detect_state_initialized = false;
static bool pi_ai_mic_detect_last_jack = false;
static bool pi_ai_mic_detect_poll_task_started = false;
#endif
