#if PI_AI_MIC_DETECT_LED_MONITOR_GPO_SERVICER_ACTIVE
static void pi_ai_mic_detect_led_set(bool valid, bool jack, bool mic, const char *tag)
{
    static uint32_t log_once = 0;

    uint32_t raw_gpo = 0xFFu;

    if (valid && jack) {
        raw_gpo &= ~(1u << GPO_LED_RED_PIN);
    }
    if (valid && mic) {
        raw_gpo &= ~(1u << GPO_LED_GREEN_PIN);
    }

    /*
     * Match the standalone PCAL LED firmware that was validated on the board:
     * write a safe-high byte and pull only the active-low LED bits low.
     */
    pi_ai_mic_raw_gpo_value = raw_gpo;

    if (!log_once) {
        printf("PI_AI_MIC GPO detect LEDs %s valid=%u jack=%u mic_square=%u raw_gpo=0x%02x\n",
               tag, valid ? 1u : 0u, jack ? 1u : 0u, mic ? 1u : 0u, (unsigned) raw_gpo);
        log_once = 1;
    }
}

static void pi_ai_mic_detect_led_apply(const char *tag)
{
    bool valid = (pi_ai_mic_boot_detect_valid != 0);
    bool jack = false;
    bool mic = false;

    if (valid) {
        jack = (pi_ai_mic_boot_detect_jack != 0);
        mic = (pi_ai_mic_boot_detect_mic_square != 0);
    }

    pi_ai_mic_detect_led_set(valid, jack, mic, tag);
}

#if PI_AI_MIC_DETECT_LED_MONITOR_GPO_SERVICER_POLL_ACTIVE
static void pi_ai_mic_detect_poll_once(const char *tag)
{
    static bool log_state_valid = false;
    static bool log_last_jack = false;
    static bool log_last_mic_square = false;
    static uint32_t poll_count = 0;

    bool valid = false;
    bool jack = false;
    bool mic_square = false;
    int ret = pi_ai_mic_read_detect_state(&valid, &jack, &mic_square);
    bool amp_write = false;

    if (ret == 0 && valid) {
        pi_ai_mic_boot_detect_valid = 1;
        pi_ai_mic_boot_detect_jack = jack ? 1 : 0;
        pi_ai_mic_boot_detect_mic_square = mic_square ? 1 : 0;

#if PI_AI_MIC_JACK_AMP_EDGE_MONITOR_ENABLE
        if (!pi_ai_mic_detect_state_initialized || jack != pi_ai_mic_detect_last_jack) {
            (void) pi_ai_mic_apply_output_route(jack, PI_AI_MIC_SPEAKER_ENABLE_WHEN_NO_JACK);
            amp_write = true;
        }
#endif
        pi_ai_mic_detect_last_jack = jack;
        pi_ai_mic_detect_state_initialized = true;

        poll_count++;
        if (!log_state_valid ||
            jack != log_last_jack ||
            mic_square != log_last_mic_square ||
            amp_write ||
            (poll_count % PI_AI_MIC_DETECT_LED_MONITOR_LOG_PERIOD) == 0) {
            printf("PI_AI_MIC GPO poll %s count=%u jack=%u mic_square=%u amp_edge_write=%u\n",
                   tag,
                   (unsigned) poll_count,
                   jack ? 1u : 0u,
                   mic_square ? 1u : 0u,
                   amp_write ? 1u : 0u);
            log_state_valid = true;
            log_last_jack = jack;
            log_last_mic_square = mic_square;
        }
    } else {
        pi_ai_mic_boot_detect_valid = 0;
        if (log_state_valid) {
            printf("PI_AI_MIC GPO poll %s read failed ret=%d valid=%u\n",
                   tag, ret, valid ? 1u : 0u);
        }
        log_state_valid = false;
    }

    pi_ai_mic_detect_led_set(ret == 0 && valid, jack, mic_square, tag);

#if PI_AI_MIC_DETECT_LED_DIAG_PULSE_ENABLE
    /*
     * Diagnostic heartbeat: briefly invert the visible LED state at each poll.
     * This proves that the 1 s live poll is running, without changing amp state
     * unless the jack edge actually changed.
     */
    uint32_t steady = pi_ai_mic_raw_gpo_value;
    uint32_t both_on = 0xFFu & ~(1u << GPO_LED_RED_PIN) & ~(1u << GPO_LED_GREEN_PIN);
    pi_ai_mic_diag_pulse_value = (steady == 0xFFu) ? both_on : 0xFFu;
    pi_ai_mic_diag_pulse_ticks =
        (GPIO_PWM_BIT_FREQUENCY * PI_AI_MIC_DETECT_LED_DIAG_PULSE_MS) / 1000u;
#endif
}

static void pi_ai_mic_detect_poll_task(void *arg)
{
    (void) arg;

    vTaskDelay(pdMS_TO_TICKS(PI_AI_MIC_DETECT_LED_MONITOR_START_DELAY_MS));

    for (;;) {
        pi_ai_mic_detect_poll_once("task");
        vTaskDelay(pdMS_TO_TICKS(PI_AI_MIC_DETECT_LED_MONITOR_PERIOD_MS));
    }
}

static void pi_ai_mic_detect_poll_task_start(void)
{
    if (pi_ai_mic_detect_poll_task_started) {
        return;
    }

    BaseType_t task_ok = xTaskCreate(
        pi_ai_mic_detect_poll_task,
        "PI_AI_MIC detect",
