        NULL,
        appconfSTARTUP_TASK_PRIORITY,
        NULL);

    if (task_ok == pdPASS) {
        pi_ai_mic_detect_poll_task_started = true;
        printf("PI_AI_MIC GPO detect poll task created period_ms=%u\n",
               (unsigned) PI_AI_MIC_DETECT_LED_MONITOR_PERIOD_MS);
    } else {
        printf("PI_AI_MIC GPO detect poll task create failed\n");
    }
}
