static void pi_ai_mic_send_user_button_state(device_control_t *device_control_ctx,
                                             button_state_t state,
                                             uint32_t press_duration)
{
    if (device_control_ctx == NULL)
    {
        return;
    }

    button_press_info_t button_info;
    button_info.gpi_source = GPI_SOURCE_EVK;
#if defined(PI_AI_MIC_USER_BUTTON_KEYBOARD_ENABLE) && PI_AI_MIC_USER_BUTTON_KEYBOARD_ENABLE
    button_info.index = KEYBOARD_SHORTCUT_BUTTON;
#else
    button_info.index = PI_AI_MIC_USER_BUTTON_PIN_INDEX;
#endif
    button_info.press_duration = press_duration;
    button_info.state = state;

    (void) send_write_cmd_to_servicer(device_control_ctx,
                                      HID_TASK_RESID,
                                      HID_TASK_RESID_INTERNAL_BUTTON_PRESS,
                                      (const uint8_t*)&button_info,
                                      sizeof(button_press_info_t),
                                      &device_control_mutex);
}

static void pi_ai_mic_user_button_poll_task(void *args)
{
    pi_ai_mic_user_button_poll_args_t *poll_args = (pi_ai_mic_user_button_poll_args_t *) args;
    xassert(poll_args != NULL);

    bool last_sample_pressed = (rtos_gpio_port_in(poll_args->gpio_ctx, poll_args->port_id) & poll_args->mask) == 0;
    bool reported_pressed = last_sample_pressed;
    uint32_t debounce_ts = get_reference_time();
    uint32_t press_ts = debounce_ts;
    uint32_t heartbeat_ts = debounce_ts;

    for (;;)
    {
        vTaskDelay(pdMS_TO_TICKS(PI_AI_MIC_USER_BUTTON_IO_POLL_MS));

        const uint32_t now = get_reference_time();
#if PI_AI_MIC_USER_BUTTON_IO_HEARTBEAT_MS
        if ((uint32_t)(now - heartbeat_ts) >= (PI_AI_MIC_USER_BUTTON_IO_HEARTBEAT_MS * XS1_TIMER_KHZ))
        {
            heartbeat_ts = now;
            pi_ai_mic_send_user_button_state(poll_args->device_control_ctx, BUTTON_STATE_PRESSED, 0);
            vTaskDelay(pdMS_TO_TICKS(20));
            pi_ai_mic_send_user_button_state(poll_args->device_control_ctx, BUTTON_STATE_RELEASED, 20 * XS1_TIMER_KHZ);
        }
#endif
        const bool sampled_pressed = (rtos_gpio_port_in(poll_args->gpio_ctx, poll_args->port_id) & poll_args->mask) == 0;

        if (sampled_pressed != last_sample_pressed)
        {
            last_sample_pressed = sampled_pressed;
            debounce_ts = now;
            continue;
        }

        const uint32_t debounce_ms = sampled_pressed ?
                                     PI_AI_MIC_USER_BUTTON_IO_DEBOUNCE_MS :
                                     PI_AI_MIC_USER_BUTTON_IO_RELEASE_DEBOUNCE_MS;

        if (sampled_pressed == reported_pressed ||
            (uint32_t)(now - debounce_ts) < (debounce_ms * XS1_TIMER_KHZ))
        {
            continue;
        }

        reported_pressed = sampled_pressed;
#if PI_AI_MIC_USER_BUTTON_EDGE_TAP_ENABLE
        pi_ai_mic_send_user_button_state(poll_args->device_control_ctx, BUTTON_STATE_PRESSED, 0);
        vTaskDelay(pdMS_TO_TICKS(20));
        pi_ai_mic_send_user_button_state(poll_args->device_control_ctx, BUTTON_STATE_RELEASED, 20 * XS1_TIMER_KHZ);
#elif PI_AI_MIC_USER_BUTTON_TAP_ON_PRESS_ENABLE
        if (reported_pressed)
        {
            pi_ai_mic_send_user_button_state(poll_args->device_control_ctx, BUTTON_STATE_PRESSED, 0);
            vTaskDelay(pdMS_TO_TICKS(20));
            pi_ai_mic_send_user_button_state(poll_args->device_control_ctx, BUTTON_STATE_RELEASED, 20 * XS1_TIMER_KHZ);
        }
#else
        if (reported_pressed)
        {
            press_ts = now;
            pi_ai_mic_send_user_button_state(poll_args->device_control_ctx, BUTTON_STATE_PRESSED, 0);
        }
        else
        {
            pi_ai_mic_send_user_button_state(poll_args->device_control_ctx, BUTTON_STATE_RELEASED, now - press_ts);
        }
#endif
    }
}
#endif

