#if ON_TILE(1)
static volatile float pi_ai_mic_raw_power[4];
static volatile unsigned pi_ai_mic_raw_sequence;

bool pi_ai_mic_read_raw_mic_levels(float levels[4])
{
    unsigned sequence = pi_ai_mic_raw_sequence;
    if (sequence == 0 || (sequence & 1))
        return false;
    asm volatile("" ::: "memory");
    for (unsigned mic = 0; mic < 4; ++mic)
        levels[mic] = pi_ai_mic_raw_power[mic];
    asm volatile("" ::: "memory");
    if (sequence != pi_ai_mic_raw_sequence)
        return false;
    for (unsigned mic = 0; mic < 4; ++mic)
        levels[mic] = sqrtf(levels[mic]);
    return true;
}

static void pi_ai_mic_measure_raw_mics(const float mics[][BECLEAR_SAMPLES_PER_FRAME])
{
    float power[4] = {0};
    for (unsigned mic = 0; mic < 4; ++mic) {
        for (unsigned sample = 0; sample < BECLEAR_SAMPLES_PER_FRAME; ++sample)
            power[mic] += mics[mic][sample] * mics[mic][sample];
        power[mic] /= BECLEAR_SAMPLES_PER_FRAME;
    }
    // Publish a bounded snapshot before BeClear overwrites the input in place.
    ++pi_ai_mic_raw_sequence;
    asm volatile("" ::: "memory");
    for (unsigned mic = 0; mic < 4; ++mic)
        pi_ai_mic_raw_power[mic] = power[mic];
    asm volatile("" ::: "memory");
    ++pi_ai_mic_raw_sequence;
}
#endif

#if PI_AI_MIC_DOA_NEOPIXEL_ENABLE
#define PI_AI_MIC_DOA_RING_JUMP_RAD          0.0872665f
#define PI_AI_MIC_DOA_RING_STABLE_FRAMES     15
#define PI_AI_MIC_TWO_PI                     (2.0f * (float)M_PI)
#ifndef PI_AI_MIC_DOA_RAW_RING_ENABLE
#define PI_AI_MIC_DOA_RAW_RING_ENABLE        1
#endif
#ifndef PI_AI_MIC_DOA_RING_OFFSET_180
#define PI_AI_MIC_DOA_RING_OFFSET_180        0
#endif
#if PI_AI_MIC_DOA_RAW_RING_ENABLE || PI_AI_MIC_RUNTIME_GEOMETRY_PROFILE_ENABLE
#define PI_AI_MIC_DOA_RAW_RING_CODE_ENABLE   1
#else
#define PI_AI_MIC_DOA_RAW_RING_CODE_ENABLE   0
#endif
#define PI_AI_MIC_RAW_DOA_SPEED_OF_SOUND     343.0f
#define PI_AI_MIC_RAW_DOA_MAX_LAG_SAMPLES    8
#define PI_AI_MIC_RAW_DOA_MIN_RMS            0.0f
#define PI_AI_MIC_RAW_DOA_MIN_CONFIDENCE     0.0f
#define PI_AI_MIC_RAW_DOA_MAX_FIT_ERROR_S    1.0f

static float pi_ai_mic_angle_delta_abs(float a, float b)
{
    float delta = fmodf(a - b + (float)M_PI, PI_AI_MIC_TWO_PI);
    if (delta < 0.0f) {
        delta += PI_AI_MIC_TWO_PI;
    }
    delta -= (float)M_PI;
    return fabsf(delta);
}

static int pi_ai_mic_doa_ring_required_stable_frames(float current_azimuth,
                                                     float candidate_azimuth)
{
#if PI_AI_MIC_RUNTIME_GEOMETRY_PROFILE_ENABLE
    if (pi_ai_mic_doa_opposite_filter_enabled() &&
        isfinite(current_azimuth) && isfinite(candidate_azimuth)) {
        float delta = pi_ai_mic_angle_delta_abs(candidate_azimuth, current_azimuth);
        float opposite_error = fabsf((float)M_PI - delta);
        if (opposite_error <= PI_AI_MIC_DOA_RING_OPPOSITE_WINDOW_RAD) {
            return pi_ai_mic_doa_opposite_stable_frames();
        }
    }
#elif PI_AI_MIC_DOA_RING_OPPOSITE_FILTER_ENABLE
    if (isfinite(current_azimuth) && isfinite(candidate_azimuth)) {
        float delta = pi_ai_mic_angle_delta_abs(candidate_azimuth, current_azimuth);
        float opposite_error = fabsf((float)M_PI - delta);
        if (opposite_error <= PI_AI_MIC_DOA_RING_OPPOSITE_WINDOW_RAD) {
            return PI_AI_MIC_DOA_RING_OPPOSITE_STABLE_FRAMES;
        }
    }
#else
    (void) current_azimuth;
    (void) candidate_azimuth;
#endif

    return PI_AI_MIC_DOA_RING_STABLE_FRAMES;
}

static float pi_ai_mic_doa_ring_select(float smoothed_azimuth, float raw_auto_azimuth)
{
#if defined(VOICEDSP_V2_CAPTURE) && VOICEDSP_V2_CAPTURE
    /* A rejected speech estimate must not become a raw-auto LED direction.
       The renderer holds the last valid direction briefly, then blanks. */
    (void) raw_auto_azimuth;
    return smoothed_azimuth;
#endif
    static float ring_azimuth = NAN;
    static float candidate_azimuth = NAN;
    static int candidate_count = 0;

    if (isfinite(smoothed_azimuth)) {
        ring_azimuth = smoothed_azimuth;
        candidate_azimuth = NAN;
        candidate_count = 0;
        return ring_azimuth;
    }

    if (!isfinite(raw_auto_azimuth)) {
        return ring_azimuth;
    }

    if (!isfinite(ring_azimuth) ||
        pi_ai_mic_angle_delta_abs(raw_auto_azimuth, ring_azimuth) <= PI_AI_MIC_DOA_RING_JUMP_RAD) {
        ring_azimuth = raw_auto_azimuth;
        candidate_azimuth = NAN;
        candidate_count = 0;
        return ring_azimuth;
    }

    if (!isfinite(candidate_azimuth) ||
        pi_ai_mic_angle_delta_abs(raw_auto_azimuth, candidate_azimuth) > PI_AI_MIC_DOA_RING_JUMP_RAD) {
        candidate_azimuth = raw_auto_azimuth;
        candidate_count = 1;
    } else {
        int required_stable_frames =
            pi_ai_mic_doa_ring_required_stable_frames(ring_azimuth, candidate_azimuth);
        if (candidate_count < required_stable_frames) {
            candidate_count++;
        }
    }

    int required_stable_frames =
        pi_ai_mic_doa_ring_required_stable_frames(ring_azimuth, candidate_azimuth);
    if (candidate_count >= required_stable_frames) {
        ring_azimuth = candidate_azimuth;
        candidate_azimuth = NAN;
        candidate_count = 0;
    }

    return ring_azimuth;
}

static float pi_ai_mic_doa_apply_ring_offset(float azimuth)
{
#if PI_AI_MIC_RUNTIME_GEOMETRY_PROFILE_ENABLE
    if (pi_ai_mic_doa_ring_offset_180() && isfinite(azimuth)) {
        azimuth = fmodf(azimuth + (float)M_PI, PI_AI_MIC_TWO_PI);
        if (azimuth < 0.0f) {
            azimuth += PI_AI_MIC_TWO_PI;
        }
    }
#elif PI_AI_MIC_DOA_RING_OFFSET_180
    if (isfinite(azimuth)) {
        azimuth = fmodf(azimuth + (float)M_PI, PI_AI_MIC_TWO_PI);
        if (azimuth < 0.0f) {
            azimuth += PI_AI_MIC_TWO_PI;
        }
    }
#endif
    return azimuth;
}

#if PI_AI_MIC_DOA_RAW_RING_CODE_ENABLE
typedef struct {
    int i;
    int j;
    float delay_s;
    float confidence;
} pi_ai_mic_pair_delay_t;

static float pi_ai_mic_raw_corr_at_lag(const float *x,
                                       const float *y,
                                       float mean_x,
                                       float mean_y,
                                       int lag)
{
    int start = lag > 0 ? lag : 0;
    int end = lag < 0 ? (BECLEAR_SAMPLES_PER_FRAME + lag) : BECLEAR_SAMPLES_PER_FRAME;
    float sum = 0.0f;
    float energy_x = 0.0f;
    float energy_y = 0.0f;

    for (int n = start; n < end; n++) {
        float a = x[n] - mean_x;
        float b = y[n - lag] - mean_y;
        sum += a * b;
        energy_x += a * a;
        energy_y += b * b;
    }

    if (!(energy_x > 0.0f) || !(energy_y > 0.0f)) {
        return 0.0f;
    }

    return sum / sqrtf((energy_x * energy_y) + 1.0e-20f);
}

static pi_ai_mic_pair_delay_t pi_ai_mic_measure_pair_delay(float raw_mics[BECLEAR_NUMBER_OF_MICS][BECLEAR_SAMPLES_PER_FRAME],
                                                           const float means[BECLEAR_NUMBER_OF_MICS],
                                                           int i,
                                                           int j)
{
    pi_ai_mic_pair_delay_t pair = {
        .i = i,
        .j = j,
        .delay_s = 0.0f,
        .confidence = 0.0f,
    };

    for (int lag = -PI_AI_MIC_RAW_DOA_MAX_LAG_SAMPLES;
         lag <= PI_AI_MIC_RAW_DOA_MAX_LAG_SAMPLES;
         lag++) {
        float corr = pi_ai_mic_raw_corr_at_lag(raw_mics[i], raw_mics[j], means[i], means[j], lag);
#if PI_AI_MIC_RUNTIME_GEOMETRY_PROFILE_ENABLE
        float abs_corr = pi_ai_mic_raw_doa_abs_correlation() ? fabsf(corr) : corr;
#elif PI_AI_MIC_RAW_DOA_ABS_CORRELATION
        float abs_corr = fabsf(corr);
#else
        float abs_corr = corr;
#endif
        if (abs_corr > pair.confidence) {
            pair.confidence = abs_corr;
            pair.delay_s = (float)lag / (float)BECLEAR_SAMPLE_FREQUENCY;
        }
    }

    if (pair.confidence < 0.0f) {
        pair.confidence = 0.0f;
    }
    return pair;
}

static float pi_ai_mic_fit_raw_doa(const pi_ai_mic_pair_delay_t pairs[6],
                                   float *fit_error_s)
{
    /*
     * Position convention matches the raw validation tool. Absolute zero can be
     * rotated later at LED calibration time; the important part is stable angle
     * separation from the four raw PDM microphones.
     */
    static const float pcb_pos[BECLEAR_NUMBER_OF_MICS][2] = {
        { -0.0333f, -0.0333f },  /* D0: bottom-left, USB on left */
        { -0.0333f, 0.0333f },   /* D1: top-left */
        { 0.0333f, 0.0333f },    /* D2: top-right */
        { 0.0333f, -0.0333f },   /* D3: bottom-right */
    };
    static const float reference_pos[BECLEAR_NUMBER_OF_MICS][2] = {
        { 0.0333f, -0.0333f },
        { 0.0333f, 0.0333f },
        { -0.0333f, 0.0333f },
        { -0.0333f, -0.0333f },
    };
#if PI_AI_MIC_RUNTIME_GEOMETRY_PROFILE_ENABLE
    const float (*pos)[2] = pi_ai_mic_raw_doa_pcb_order() ? pcb_pos : reference_pos;
#elif PI_AI_MIC_RAW_DOA_PCB_ORDER
    const float (*pos)[2] = pcb_pos;
#else
    const float (*pos)[2] = reference_pos;
#endif
    float best_angle_rad = NAN;
    float best_score = 1.0e30f;
#if PI_AI_MIC_RUNTIME_GEOMETRY_PROFILE_ENABLE
    float delay_signs[2];
    unsigned delay_sign_count = 0;
    int configured_delay_sign = pi_ai_mic_raw_doa_delay_sign();
    if (configured_delay_sign > 0) {
        delay_signs[delay_sign_count++] = 1.0f;
    } else if (configured_delay_sign < 0) {
        delay_signs[delay_sign_count++] = -1.0f;
    } else {
        delay_signs[delay_sign_count++] = 1.0f;
        delay_signs[delay_sign_count++] = -1.0f;
    }
#else
    static const float delay_signs[] = {
#if PI_AI_MIC_RAW_DOA_DELAY_SIGN > 0
        1.0f
#elif PI_AI_MIC_RAW_DOA_DELAY_SIGN < 0
        -1.0f
#else
        1.0f, -1.0f
#endif
    };
#define PI_AI_MIC_DELAY_SIGN_COUNT (sizeof(delay_signs) / sizeof(delay_signs[0]))
#endif

    for (unsigned sign_i = 0;
#if PI_AI_MIC_RUNTIME_GEOMETRY_PROFILE_ENABLE
         sign_i < delay_sign_count;
#else
         sign_i < PI_AI_MIC_DELAY_SIGN_COUNT;
#endif
         sign_i++) {
        float sign = delay_signs[sign_i];

        for (int deg = 0; deg < 360; deg += 5) {
            float theta = (float)deg * ((float)M_PI / 180.0f);
            float dir_x = cosf(theta);
            float dir_y = sinf(theta);
            float arrivals[BECLEAR_NUMBER_OF_MICS];
            float weighted_error = 0.0f;
            float weight_sum = 0.0f;

            for (int mic = 0; mic < BECLEAR_NUMBER_OF_MICS; mic++) {
                arrivals[mic] = -((pos[mic][0] * dir_x) + (pos[mic][1] * dir_y)) /
                                PI_AI_MIC_RAW_DOA_SPEED_OF_SOUND;
            }

            for (int pair_i = 0; pair_i < 6; pair_i++) {
                const pi_ai_mic_pair_delay_t *pair = &pairs[pair_i];
                float predicted = arrivals[pair->i] - arrivals[pair->j];
                float measured = sign * pair->delay_s;
                float error = measured - predicted;
                float weight = pair->confidence;
                weighted_error += weight * error * error;
                weight_sum += weight;
            }

            if (weight_sum > 0.0f) {
                float score = weighted_error / weight_sum;
                if (score < best_score) {
                    best_score = score;
                    best_angle_rad = theta;
                }
            }
        }
    }

    if (fit_error_s != NULL) {
        *fit_error_s = sqrtf(best_score);
    }

    return best_angle_rad;
}

static float pi_ai_mic_raw_square_doa(float raw_mics[BECLEAR_NUMBER_OF_MICS][BECLEAR_SAMPLES_PER_FRAME],
                                      float *energy_out)
{
    float means[BECLEAR_NUMBER_OF_MICS] = {0.0f};
    float rms_sum = 0.0f;

    for (int mic = 0; mic < BECLEAR_NUMBER_OF_MICS; mic++) {
        float sum = 0.0f;
        for (int n = 0; n < BECLEAR_SAMPLES_PER_FRAME; n++) {
            sum += raw_mics[mic][n];
        }
        means[mic] = sum / (float)BECLEAR_SAMPLES_PER_FRAME;
    }

    for (int mic = 0; mic < BECLEAR_NUMBER_OF_MICS; mic++) {
        float energy = 0.0f;
        for (int n = 0; n < BECLEAR_SAMPLES_PER_FRAME; n++) {
            float sample = raw_mics[mic][n] - means[mic];
            energy += sample * sample;
        }
        rms_sum += sqrtf(energy / (float)BECLEAR_SAMPLES_PER_FRAME);
    }

    float rms = rms_sum / (float)BECLEAR_NUMBER_OF_MICS;
    if (energy_out != NULL) {
        *energy_out = rms;
    }
    if (!(rms > PI_AI_MIC_RAW_DOA_MIN_RMS)) {
        return NAN;
    }

    pi_ai_mic_pair_delay_t pairs[6];
    int pair_i = 0;
    float confidence_sum = 0.0f;
    for (int i = 0; i < BECLEAR_NUMBER_OF_MICS; i++) {
        for (int j = i + 1; j < BECLEAR_NUMBER_OF_MICS; j++) {
            pairs[pair_i] = pi_ai_mic_measure_pair_delay(raw_mics, means, i, j);
            confidence_sum += pairs[pair_i].confidence;
            pair_i++;
        }
    }

    float mean_confidence = confidence_sum / 6.0f;
    if (!(mean_confidence > PI_AI_MIC_RAW_DOA_MIN_CONFIDENCE)) {
        return NAN;
    }

    float fit_error_s = 0.0f;
    float angle = pi_ai_mic_fit_raw_doa(pairs, &fit_error_s);
    if (!isfinite(angle) || !(fit_error_s < PI_AI_MIC_RAW_DOA_MAX_FIT_ERROR_S)) {
        return NAN;
    }

    return angle;
}
#endif
#endif

