      hid_report_config_t *report_config = get_input_report(hid_task_args->hid_input_report_config, REPORT_ID_KEYBOARD_SHORTCUT);
      xassert(report_config != NULL);

      if(keyboardlike_release_stage == KEYBOARDLIKE_RELEASE_D_UP_MODIFIERS_HELD)
      {
        set_keyboard_shortcut_modifier_only_report(report_config->report);
