      }
      else
      {
        set_keyboard_shortcut_report(report_config->report, BUTTON_STATE_RELEASED);
      }

      pending_report = send_hid_report_wrapper(report_config, true);
      if(pending_report == NULL)
      {
        if(keyboardlike_release_stage == KEYBOARDLIKE_RELEASE_D_UP_MODIFIERS_HELD)
        {
          keyboardlike_release_stage = KEYBOARDLIKE_RELEASE_SHIFT_UP_CTRL_HELD;
          keyboardlike_release_next_ts = get_reference_time() + (PI_AI_MIC_USER_BUTTON_KEYBOARDLIKE_RELEASE_D_UP_MS * NUM_TICKS_PER_MS);
        }
        else if(keyboardlike_release_stage == KEYBOARDLIKE_RELEASE_SHIFT_UP_CTRL_HELD)
