        {
          keyboardlike_release_empty_remaining = PI_AI_MIC_USER_BUTTON_KEYBOARDLIKE_RELEASE_EMPTY_COUNT;
          keyboardlike_release_stage = keyboardlike_release_empty_remaining > 0 ? KEYBOARDLIKE_RELEASE_EMPTY_BURST
                                                                                : KEYBOARDLIKE_RELEASE_IDLE;
          keyboardlike_release_next_ts = get_reference_time();
        }
        else if(keyboardlike_release_stage == KEYBOARDLIKE_RELEASE_EMPTY_BURST)
        {
          if(keyboardlike_release_empty_remaining > 0)
          {
            keyboardlike_release_empty_remaining--;
          }
          keyboardlike_release_stage = keyboardlike_release_empty_remaining > 0 ? KEYBOARDLIKE_RELEASE_EMPTY_BURST
